input.sparql:
SELECT ?point ?tsid ?pclass WHERE {
  ?zone brick:hasPoint ?point .
  ?zone brick:hasPoint/rdfs:label ?lbl .
  ?point ref:hasTimeseriesId ?tsid .
  FILTER(?lbl IN ("Perimeter_mid_ZN_2","Core_top"))
}

SELECT ?zone ?point ?tsid ?pclass WHERE {
  ?point brick:isPointOf ?zone .
  ?point a ?pclass .
  OPTIONAL { ?point ref:hasTimeseriesId ?tsid }
  FILTER(?zone IN ("Perimeter_mid_ZN_2","Core_top"))
}

SELECT ?zone ?zlabel WHERE {
  ?zone a brick:Zone .
  OPTIONAL { ?zone rdfs:label ?zlabel }
} LIMIT 30

SELECT ?point ?zone ?tsid WHERE {
  ?point a brick:Zone_Air_Temperature_Sensor .
  ?point brick:isPointOf ?zone .
  OPTIONAL { ?point ref:hasTimeseriesId ?tsid }
} LIMIT 200

SELECT ?b ?btype ?naming ?numzones ?ztype ?spatial WHERE {
  ?b a brick:Building .
  OPTIONAL { ?b buildgraph:meta:vintage ?v }
}

SELECT ?s ?label ?ifcname ?zoneType ?spatial WHERE {
  ?s a brick:HVAC_Zone .
  OPTIONAL { ?s rdfs:label ?label }
  OPTIONAL { ?s ref:ifcName ?ifcname }
  OPTIONAL { ?s ?zt ?zoneType . FILTER(strstarts(str(?zt),"http://buildgraph.org/meta#")) }
} LIMIT 200

